page_heading('PLAN & COORDINATE',$page==='calendar'?'Workforce calendar':($service->manager()?'Master schedule':'My schedule'),'Authorized duty and deployment assignments, together in one view.',add_link('?page=schedule&new=1','Add schedule'));
if($page==='schedule' && (isset($_GET['new']) || isset($_GET['edit']))) {
